import { chmod, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

/**
 * Where generated export files live until they expire. The pilot uses a private directory on the
 * server; a cloud deployment supplies an object-storage implementation of the same interface
 * (private bucket, server-side encryption, no public or long-lived links). Keys are generated by
 * the server and validated here, so a key can never name a path outside the store.
 */
export interface ExportStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

export class LocalDiskStorage implements ExportStorage {
  constructor(private readonly dir: string) {}

  private path(key: string): string {
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('invalid storage key');
    return join(this.dir, key);
  }

  async put(key: string, data: Buffer): Promise<void> {
    await mkdir(this.dir, { recursive: true, mode: 0o700 });
    // 'wx': never overwrite an existing file. Owner-only permissions.
    await writeFile(this.path(key), data, { flag: 'wx', mode: 0o600 });
    await chmod(this.path(key), 0o600).catch(() => undefined);
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.path(key));
  }

  async delete(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }
}

/** In-memory store for tests that should not touch the disk. */
export class MemoryStorage implements ExportStorage {
  readonly files = new Map<string, Buffer>();

  async put(key: string, data: Buffer): Promise<void> {
    if (!SAFE_KEY.test(key)) throw new Error('invalid storage key');
    if (this.files.has(key)) throw new Error('exists');
    this.files.set(key, data);
  }

  async get(key: string): Promise<Buffer> {
    const f = this.files.get(key);
    if (!f) throw new Error('not found');
    return f;
  }

  async delete(key: string): Promise<void> {
    this.files.delete(key);
  }
}
